<script setup lang="ts">import {computed,ref} from 'vue';import {useRouter} from 'vue-router';import AppShell from '@/components/zs/AppShell.vue';import PageHeader from '@/components/zs/PageHeader.vue';import Panel from '@/components/zs/Panel.vue';import DataTable from '@/components/zs/DataTable.vue';import Toolbar from '@/components/zs/Toolbar.vue';import SearchInput from '@/components/zs/SearchInput.vue';import StatusBadge from '@/components/zs/StatusBadge.vue';import UserAvatar from '@/components/crm/UserAvatar.vue';import Pagination from '@/components/zs/Pagination.vue';import SidePanel from '@/components/zs/SidePanel.vue';import Field from '@/components/zs/Field.vue';import ZButton from '@/components/zs/ZButton.vue';import {useCrmData} from '@/composables/useCrmData';import type {CrmContact} from '@/types/crm';import {setPageMeta} from '@/lib/page-meta';setPageMeta('Contacts','People and decision makers across CRM accounts.');const d=useCrmData(),router=useRouter(),q=ref(''),page=ref(1),open=ref(false),editing=ref<CrmContact|null>(null);const columns=[{key:'name',header:'Name'},{key:'company',header:'Company'},{key:'title',header:'Job title'},{key:'email',header:'Email'},{key:'phone',header:'Phone'},{key:'linkedin',header:'LinkedIn'},{key:'owner',header:'Owner'},{key:'status',header:'Status'},{key:'lastActivity',header:'Last activity'},{key:'actions',header:'',align:'right' as const}];const all=computed(()=>(d.contacts.data.value??[]).filter(x=>`${x.name} ${x.company}`.toLowerCase().includes(q.value.toLowerCase())));const rows=computed(()=>all.value.slice((page.value-1)*7,page.value*7));function edit(x?:CrmContact){editing.value=x?structuredClone(x):{id:'new',companyId:d.activeCompanyId.value,name:'',accountId:'',company:'',title:'',email:'',phone:'',linkedin:'',owner:'',status:'Active',lastActivity:''};open.value=true}</script>
<template><AppShell><PageHeader title="Contacts" :description="`${all.length} people across client accounts`"><template #actions><ZButton @click="edit()">Add contact</ZButton></template></PageHeader><Panel><Toolbar><SearchInput v-model="q" placeholder="Search contact or company"/></Toolbar><DataTable :columns="columns" :rows="rows" :min-width="1280"><template #name="{row}"><button class="flex items-center gap-2 font-medium text-content" @click="router.push(`/crm/contacts/${row.id}`)"><UserAvatar :name="row.name"/>{{row.name}}</button></template><template #linkedin="{row}"><span class="text-xs text-primary">{{row.linkedin}}</span></template><template #status="{row}"><StatusBadge :status="row.status"/></template><template #actions="{row}"><ZButton variant="ghost" @click="edit(row)">Edit</ZButton></template><template #footer><Pagination :page="page" :pages="Math.ceil(all.length/7)" :total="all.length" @change="page=$event"/></template></DataTable></Panel><SidePanel :open="open" :title="editing?.id==='new'?'Add contact':'Edit contact'" @close="open=false"><form class="grid gap-4 sm:grid-cols-2" @submit.prevent="open=false"><Field v-if="editing" v-model="editing.name" label="Full name" required/><Field v-if="editing" v-model="editing.company" label="Company" required/><Field v-if="editing" v-model="editing.title" label="Job title"/><Field v-if="editing" v-model="editing.email" label="Email" type="email" required/><Field v-if="editing" v-model="editing.phone" label="Phone"/><Field v-if="editing" v-model="editing.linkedin" label="LinkedIn"/><Field v-if="editing" v-model="editing.owner" label="Owner" required/><ZButton type="submit">Save contact</ZButton></form></SidePanel></AppShell></template>
